<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Bus; use Illuminate\Http\Request;
class BusController extends Controller { public function index(Request $r){$buses=Bus::when($r->q,fn($q,$v)=>$q->where('name','like',"%$v%")->orWhere('corridor_number','like',"%$v%"))->latest()->paginate(10)->withQueryString();return view('admin.buses.index',compact('buses'));} public function create(){return view('admin.buses.form',['bus'=>new Bus]);} public function store(Request $r){Bus::create($this->data($r));return redirect()->route('admin.buses.index')->with('success','Bus berhasil ditambahkan.');} public function edit(Bus $bus){return view('admin.buses.form',compact('bus'));} public function update(Request $r,Bus $bus){$bus->update($this->data($r,$bus));return redirect()->route('admin.buses.index')->with('success','Bus diperbarui.');} public function destroy(Bus $bus){$bus->delete();return back()->with('success','Bus dihapus.');} private function data(Request $r,?Bus $bus=null){return $r->validate(['name'=>'required|max:100','code'=>'required|max:30|unique:buses,code,'.($bus?->id),'corridor_number'=>'required|max:30','color'=>'required|max:20','description'=>'nullable','estimated_minutes'=>'nullable|integer|min:1','is_active'=>'boolean'])+['is_active'=>$r->boolean('is_active')];} }
